const t={tuning:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Procedure guidate di calibrazione. Si parte da: Pressure Advance."}},params:{start:{t:0,b:{t:2,i:[{t:3}],s:"PA iniziale"}},factor:{t:0,b:{t:2,i:[{t:3}],s:"Fattore (PA/mm)"}},height:{t:0,b:{t:2,i:[{t:3}],s:"Altezza (mm)"}}},pa:{title:{t:0,b:{t:2,i:[{t:3}],s:"Pressure Advance"}},step1:{t:0,b:{t:2,i:[{t:3}],s:"1. Pianifica la torre di taratura"}},plan:{t:0,b:{t:2,i:[{t:3}],s:"Pianifica torre"}},command:{t:0,b:{t:2,i:[{t:3}],s:"Esegui questo comando"}},commandHint:{t:0,b:{t:2,i:[{t:3}],s:"Invialo subito prima della stampa (oppure aggiungilo allo start g-code del tuo modello di prova); il PA aumenta gradualmente lungo la torre man mano che stampa."}},table:{height:{t:0,b:{t:2,i:[{t:3}],s:"Altezza (mm)"}},pa:{t:0,b:{t:2,i:[{t:3}],s:"PA"}}},step2:{t:0,b:{t:2,i:[{t:3}],s:"2. Inserisci l'altezza dal risultato migliore"}},bestHeight:{t:0,b:{t:2,i:[{t:3}],s:"Altezza Z migliore (mm)"}},computed:{t:0,b:{t:2,i:[{t:3,v:"Pressure Advance calcolato: "},{t:4,k:"pa"}]}},applyButton:{t:0,b:{t:2,i:[{t:3}],s:"Applica PA"}},apply:{applied:{t:0,b:{t:2,i:[{t:3,v:"Pressure Advance "},{t:4,k:"value"},{t:3,v:" applicato"}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:"La stampante è occupata - impossibile applicare ora"}},out_of_range:{t:0,b:{t:2,i:[{t:3,v:"Valore fuori intervallo (max "},{t:4,k:"max"},{t:3,v:")"}]}},moonraker_error:{t:0,b:{t:2,i:[{t:3,v:"Impossibile applicare: "},{t:4,k:"error"}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Guida"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Guida al Pressure Advance"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Chiudi"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Cos'è il Pressure Advance?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Il PA compensa il ritardo di pressione nell'ugello, rendendo gli angoli più netti e riducendo colature e rigonfiamenti. Ogni filamento ha il proprio valore ottimale."}}},workflow:{title:{t:0,b:{t:2,i:[{t:3}],s:"Come funziona la procedura guidata"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Pianifica una torre di taratura, stampala (il PA aumenta man mano che sale), individua l'altezza più pulita, poi applica il valore corrispondente. Salvalo in printer.cfg per mantenerlo."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Glossario"}}}},glossary:{pressureAdvance:{term:{t:0,b:{t:2,i:[{t:3}],s:"Pressure Advance"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Un'impostazione di Klipper che regola l'estrusione in anticipo rispetto ai cambi di velocità per ottenere angoli più netti."}}},tuningTower:{term:{t:0,b:{t:2,i:[{t:3}],s:"Torre di taratura"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Una stampa alta in cui TUNING_TOWER modifica progressivamente un parametro con l'altezza, così puoi scegliere il layer migliore."}}}}}}};export{t as default};
